<template><view class="editor-mask" @touchmove.stop><view class="editor-sheet"><view class="sheet-grip"/><view class="editor-heading"><view><text class="editor-title">把主角放进模板里</text><text class="editor-sub">单指挪位置 · 双指捏合缩放 · 窗口内就是要上传的画面</text></view><button class="editor-close" aria-label="关闭图片编辑" @click="$emit('close')">×</button></view><scroll-view scroll-y class="editor-scroll" :style="{height:bodyHeight+'px'}"><view class="editor-inner"><view class="guide-status"><text>{{guideLoading?'正在打开模板参照…':guide?.generic?'自由裁剪 · 单指移动，双指缩放':'对照模板 · 图片 '+(activeIndex+1)}}</text><button @click="showGuide=!showGuide">{{showGuide?'隐藏参照':'显示参照'}}</button></view><view class="alignment-stage" :style="{width:stageWidth+'px',height:stageHeight+'px'}"><image v-if="previewImage && showGuide" :src="previewImage" class="ghost-template" mode="scaleToFill"/><view class="target-window checker" :style="windowStyle" @touchstart="start" @touchmove.stop.prevent="move" @touchend="end" @touchcancel="drag=null" @mousedown.stop.prevent="start" @mousemove="move" @mouseup="drag=null" @mouseleave="drag=null"><image :src="src" :style="imageStyle" mode="aspectFit"/></view><image v-if="overlay && showGuide" :src="overlay" class="guide-overlay" mode="scaleToFill"/><view class="window-outline" :style="windowStyle"><view class="corner tl"/><view class="corner tr"/><view class="corner bl"/><view class="corner br"/></view><view v-if="busy" class="processing"><view class="editor-spinner"/><text>正在把主角准备好…</text></view></view><view class="gesture-caption"><text>框外只是参照，框内才是主角</text><button @click="reset">复位</button></view><view v-if="guide?.generic" class="ratios"><button v-for="r in ratios" :key="r.label" :class="{chosen:effectiveRatio===r.value}" @click="fallbackRatio=r.value;reset()">{{r.label}}</button></view><view v-if="images.length>1" class="editor-thumbnails"><button v-for="(path,index) in images" :key="index" :class="{selected:index===activeIndex}" @click="!busy && $emit('select',index)"><image :src="path" mode="aspectFill"/><text>{{index+1}}</text></button></view><view class="editor-tools"><button :disabled="busy" @click="$emit('edit',{type:'flip'})"><ui-icon name="flip"/><text>左右翻转</text></button><button :disabled="busy" @click="$emit('edit',{type:'rotate'})"><ui-icon name="rotate"/><text>旋转 90°</text></button><button :disabled="busy" @click="zoom=Math.min(8,zoom+0.25)"><ui-icon name="plus"/><text>放大一点</text></button></view><button v-if="allowBackground" class="background-tool" :disabled="busy" @click="$emit('edit',{type:'background'})"><ui-icon name="cutout"/><view><text>一键抠图 · 留下主角</text><text class="tool-sub">照片、宠物、物品都可以试试，透明背景实时预览</text></view></button><text v-if="error" class="editor-error">{{error}}</text><view class="editor-history"><button :disabled="busy || !canUndo" @click="$emit('undo')">撤销上一步</button><button :disabled="busy || !canUndo" @click="$emit('restore')">还原上传图</button><text>{{zoom.toFixed(1)}}×</text></view></view></scroll-view><view class="done-bar"><button class="ui-primary" :disabled="busy || guideLoading || !info.width" @click="confirm">截取窗口，就用这张 <ui-icon name="check" tone="white"/></button></view></view></view></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {cropGeometry} from '@/services/imageEditing'
import {apiRequest} from '@/services/apiService'
import {visitorHeaders} from '@/services/popularityService'
import {API_BASE_URL} from '@/constants'
import UiIcon from '@/components/UiIcon.vue'
const props=defineProps({src:String,templateKey:String,previewImage:String,allowBackground:{type:Boolean,default:true},images:{type:Array,default:()=>[]},activeIndex:{type:Number,default:0},busy:Boolean,error:String,canUndo:Boolean})
const emit=defineEmits(['close','select','edit','undo','restore'])
const win=uni.getWindowInfo?.()||uni.getSystemInfoSync(),info=ref({width:0,height:0}),guide=ref(null),overlay=ref(''),guideLoading=ref(false),showGuide=ref(true),zoom=ref(1),offsetX=ref(0),offsetY=ref(0),fallbackRatio=ref(0)
const bodyHeight=Math.max(240,win.windowHeight-265),maxWidth=Math.min(win.windowWidth-36,420)
let drag=null,epoch=0
const reset=()=>{zoom.value=1;offsetX.value=0;offsetY.value=0}
watch(()=>props.activeIndex,reset)
watch(()=>props.src,path=>{const version=++epoch,previous=info.value;info.value={width:0,height:0};if(path)uni.getImageInfo({src:path,success:r=>{if(epoch!==version)return;if(previous.width!==r.width || previous.height!==r.height)reset();info.value=r},fail:()=>{}})},{immediate:true})
watch(()=>props.templateKey,async key=>{guideLoading.value=true;guide.value=null;overlay.value='';if(!key){guide.value={generic:true};guideLoading.value=false;return}try{const data=await apiRequest(`/images/templates/${encodeURIComponent(key)}/guide`,{header:visitorHeaders(),timeout:30000},1);if(key!==props.templateKey)return;guide.value=data;const file=await new Promise((resolve,reject)=>uni.downloadFile({url:API_BASE_URL+data.overlay_url,header:visitorHeaders(),timeout:20000,success:r=>r.statusCode===200?resolve(r.tempFilePath):reject(Error()),fail:reject}));if(key===props.templateKey)overlay.value=file}catch(_){if(key===props.templateKey)guide.value={generic:true}}finally{if(key===props.templateKey)guideLoading.value=false}},{immediate:true})
const canvasRatio=computed(()=>guide.value&&!guide.value.generic?guide.value.width/guide.value.height:1)
const stageWidth=computed(()=>Math.min(maxWidth,Math.min(360,win.windowHeight*.39)*canvasRatio.value)),stageHeight=computed(()=>stageWidth.value/canvasRatio.value)
const effectiveRatio=computed(()=>fallbackRatio.value || (info.value.width||1)/(info.value.height||1))
const target=computed(()=>{if(guide.value && !guide.value.generic){const windows=guide.value.windows.filter(w=>w.slot===props.activeIndex).sort((a,b)=>b.box[2]*b.box[3]-a.box[2]*a.box[3]);if(windows[0]){const [x,y,w,h]=windows[0].box,k=stageWidth.value/guide.value.width;return{x:x*k,y:y*k,w:w*k,h:h*k}}}const w=Math.min(stageWidth.value-24,(stageHeight.value-24)*effectiveRatio.value),h=w/effectiveRatio.value;return{x:(stageWidth.value-w)/2,y:(stageHeight.value-h)/2,w,h}})
const geometry=computed(()=>cropGeometry(info.value.width||1,info.value.height||1,target.value.w,target.value.h,zoom.value,offsetX.value,offsetY.value))
const windowStyle=computed(()=>({left:target.value.x+'px',top:target.value.y+'px',width:target.value.w+'px',height:target.value.h+'px'}))
const imageStyle=computed(()=>({position:'absolute',width:geometry.value.width+'px',height:geometry.value.height+'px',maxWidth:'none',left:((target.value.w-geometry.value.width)/2+geometry.value.x)+'px',top:((target.value.h-geometry.value.height)/2+geometry.value.y)+'px',pointerEvents:'none'}))
const ratios=computed(()=>[{label:'方形',value:1},{label:'竖版',value:.75},{label:'横版',value:4/3},{label:'原比例',value:(info.value.width||1)/(info.value.height||1)}])
const point=e=>{const a=e.touches?.[0]||e,b=e.touches?.[1];return{x:b?(a.clientX+b.clientX)/2:a.clientX,y:b?(a.clientY+b.clientY)/2:a.clientY,d:b?Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY):0,n:e.touches?.length||1}}
const start=e=>{if(props.busy||guideLoading.value)return;const p=point(e);drag={...p,z:zoom.value,dx:geometry.value.x,dy:geometry.value.y}}
const move=e=>{if(!drag||(!e.touches&&!e.buttons))return;const p=point(e);if(p.n!==drag.n){start(e);return}if(p.d&&drag.d)zoom.value=Math.max(1,Math.min(8,drag.z*p.d/drag.d));offsetX.value=drag.dx+p.x-drag.x;offsetY.value=drag.dy+p.y-drag.y}
const end=e=>{if(e.touches?.length)start(e);else drag=null}
const confirm=()=>emit('edit',{type:'crop',rect:geometry.value.rect,complete:true})
</script>
<style scoped>
.editor-mask{position:fixed;inset:0;z-index:2600;background:#20363888;display:flex;align-items:flex-end;justify-content:center}.editor-sheet{width:100%;max-width:850rpx;background:var(--paper);border:3rpx solid white;border-radius:38rpx 38rpx 0 0;max-height:calc(100vh - 90px);overflow:hidden;animation:ui-sheet .25s ease-out}.sheet-grip{width:64rpx;height:7rpx;border-radius:8rpx;background:#ded8ce;margin:14rpx auto}.editor-heading{display:flex;align-items:center;gap:20rpx;padding:16rpx 28rpx 20rpx}.editor-heading>view{flex:1}.editor-title{display:block;font-size:32rpx;font-weight:750}.editor-sub{display:block;font-size:20rpx;color:#929685;line-height:1.7;margin-top:5rpx}.editor-close{width:66rpx;height:66rpx;border-radius:22rpx;font-size:34rpx;background:#f4eee6;color:#a49788}.editor-inner{padding:0 22rpx 20rpx}.guide-status{display:flex;justify-content:space-between;align-items:center;font-size:21rpx;color:#9a947f;padding:8rpx 0 17rpx}.guide-status button,.gesture-caption button{font-size:22rpx;color:#c7805c}.alignment-stage{position:relative;margin:auto;background:#e8e5db;border:2rpx solid #fff;border-radius:20rpx;overflow:hidden}.ghost-template,.guide-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.ghost-template{opacity:.25;filter:blur(1px)}.guide-overlay{opacity:.8}.target-window{position:absolute;overflow:hidden;touch-action:none;background-color:white;background-image:conic-gradient(#e9e8e0 25%,white 0 50%,#e9e8e0 0 75%,white 0);background-size:18px 18px}.window-outline{position:absolute;pointer-events:none;border:1px dashed #ffb47d;box-shadow:0 0 0 1px #ffffff88}.corner{position:absolute;width:17px;height:17px;border:3px solid #ff9d72}.tl{left:-2px;top:-2px;border-right:0;border-bottom:0}.tr{right:-2px;top:-2px;border-left:0;border-bottom:0}.bl{left:-2px;bottom:-2px;border-right:0;border-top:0}.br{right:-2px;bottom:-2px;border-left:0;border-top:0}.gesture-caption{display:flex;justify-content:space-between;align-items:center;font-size:21rpx;color:#a99d88;margin:18rpx 0}.editor-tools{display:flex;gap:12rpx;margin:20rpx 0}.editor-tools button{flex:1;background:#fff;border:2rpx solid #f1e7db;border-radius:23rpx;min-height:110rpx;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12rpx;font-size:22rpx;color:#8c8d7b}.background-tool{display:flex;gap:18rpx;align-items:center;width:100%;background:#e5eee3;padding:22rpx;border-radius:24rpx;text-align:left;font-size:26rpx;color:#4c7b67;line-height:1.6}.tool-sub{display:block;font-size:20rpx;color:#8a9f85}.editor-history{display:flex;align-items:center;gap:15rpx;margin-top:12rpx;color:#a79b88;font-size:21rpx}.editor-history button{font-size:22rpx;color:#8e9681;padding:14rpx 4rpx}.editor-history>text{margin-left:auto}.done-bar{padding:18rpx 24rpx calc(20rpx + env(safe-area-inset-bottom));border-top:2rpx solid #efe7dc}.done-bar button{width:100%;gap:15rpx;font-size:26rpx}.processing{position:absolute;inset:0;background:#fff8eceb;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20rpx;font-size:24rpx;color:#a18b6c}.editor-spinner{width:42rpx;height:42rpx;border:4rpx solid #efd4bc;border-top-color:#ef966d;border-radius:50%;animation:ui-spin .8s linear infinite}.editor-error{display:block;background:#fff0df;color:#b87855;font-size:23rpx;padding:20rpx;border-radius:20rpx;margin:15rpx 0}.ratios{display:flex;gap:10rpx}.ratios button{flex:1;background:#f1ede4;border-radius:16rpx;padding:14rpx 3rpx;font-size:21rpx;color:#9c9684}.ratios .chosen{background:#ffe3ca;color:#c27d55}.editor-thumbnails{display:flex;gap:12rpx;margin:18rpx 0}.editor-thumbnails button{width:75rpx;height:75rpx;position:relative;border:3rpx solid transparent;padding:0;overflow:hidden;border-radius:15rpx}.editor-thumbnails .selected{border-color:#e99367}.editor-thumbnails image{width:100%;height:100%}.editor-thumbnails text{position:absolute;right:0;bottom:0;background:#fff7df;font-size:17rpx;padding:2rpx 8rpx}button[disabled]{opacity:.45}
</style>
